import { test, expect } from '@playwright/test';

test.describe('Checkout Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should complete the checkout flow in order', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Checkout' }).click();
    await expect(page.getByText('Shipping Information')).toBeVisible();

    await page.getByLabel('Full Name').fill('John Doe');
    await page.getByLabel('Address').fill('123 Main St');
    await page.getByRole('button', { name: 'Continue to Payment' }).click();

    await expect(page.getByText('Payment Information')).toBeVisible();
    await page.getByLabel('Credit Card Number').fill('4111111111111111');
    await page.getByLabel('Expiration Date').fill('12/25');
    await page.getByRole('button', { name: 'Complete Order' }).click();

    await expect(page.getByText('Thank you for your order!')).toBeVisible();
  });

  test('should show error for incomplete shipping information', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Checkout' }).click();
    await expect(page.getByText('Shipping Information')).toBeVisible();

    await page.getByLabel('Full Name').fill(''); // Leave full name empty
    await page.getByRole('button', { name: 'Continue to Payment' }).click();

    await expect(page.getByText('Please fill out this field.')).toBeVisible();
  });
});
